# trainfast copy of train85/scripts/env_train.sh (2026-10-31); only the NFS fallback for the per-job HOME is trainfast/jobs.
# Generated by train85 from $E/env.sh (sha256 396f917d47fbcfbb, 2026-10-14): identical except that the NFS fallback for the
# per-job HOME / caches (nodes with <= 30 GB free in /tmp) is $TRAIN/jobs/<job> instead of $E/jobs/<job>, so train jobs write nothing under $E.
# Eval-instance sampling of the representative sheet (eval branch = merge/v3.0-reconciled+lab-vec-eval-next and its successors).
# Sourced by the job scripts with ISGE_CODE = a frozen snapshot (snapshot.sh): code, Behavior-1K and the OmniGibson data path
# (Behavior-1K/datasets of the snapshot, ispatialgym-assets = the snapshot's own custom assets) all come from it.
# Reads only: the conda env, the shared datasets. Writes only the job's own directories (or under $E outside a job).
# of-v2maps 2026-11-07 (shiyuc mode, submit_fast.py --shiyuc): ISGF_JB_NFS / ISGF_LAB_BAND_STORE / ISGF_EVAL_BANDS / ISGF_REACH_VOLUME_SRC
# from job.env move the NFS fallback and the read stores to /vision/u/shiyuc/minyeong (unset: as before).
E=/vision/u/minyeong/projects/isg_home/eval85
R=${ISGE_CODE:?set ISGE_CODE to a snapshot made by $E/snapshot.sh}
if [ -n "${SLURM_JOB_ID:-}" ]; then
  # Kit app data warm from the NFS template of this GPU + driver + Behavior-1K commit ($KIT_TPL_NFS_ROOT), texture cache linked to
  # the shared store unless KIT_TEX=0 (cluster_tools/README.md)
  WT=$R
  source /vision/u/minyeong/projects/cluster_tools/kit_appdata.sh
  kit_appdata_setup
fi
source /vision/u/minyeong/miniconda3/etc/profile.d/conda.sh
conda activate ispatialgym-vectorized-envs
export PYTHONPATH=$R:$R/Behavior-1K/OmniGibson:$R/Behavior-1K/bddl3
export OMNIGIBSON_DATA_PATH=$R/Behavior-1K/datasets
export OMNIGIBSON_HEADLESS=1 OMNI_KIT_ACCEPT_EULA=YES HDF5_USE_FILE_LOCKING=FALSE HF_HUB_OFFLINE=1
export OMNIGIBSON_TRACK_STATE_UPDATES=1
# the reconcile / production settings (isg_home/reconcile/env.sh): threads, numpy change detection, the six exact opt-ins,
# production's data format and sampler; the non-bitwise / experimental switches off
export OMP_NUM_THREADS=1 OMNIGIBSON_CHANGE_DETECTION_NUMPY=1
export ISPATIALGYM_FAST_GEOMETRY=1 ISPATIALGYM_FAST_SUPPORT=1 ISPATIALGYM_FAST_ASSIGN=1 ISPATIALGYM_SHARED_GOAL_EVAL=1 \
  ISPATIALGYM_GC_FREEZE=1 ISPATIALGYM_BATCHED_WORLD_SYNC=1
export ISPATIALGYM_SHARD_FORMAT=legacy ISPATIALGYM_SEEDED_SPHERE_FIT=off
unset ISPATIALGYM_EXECUTOR_MESH_CACHE ISPATIALGYM_PHYSICS_ONLY ISPATIALGYM_ASYNC_SHARD ISPATIALGYM_PER_SCENE_STATE ISPATIALGYM_ASYNC_FRAMES \
  ISPATIALGYM_RECORD_LINK_POSES ISPATIALGYM_SAMPLER_MESH_CACHE ISPATIALGYM_SAMPLER_STEP1_ONCE ISPATIALGYM_HEAD_CAMERA_ONLY ISG_PROGRAM_HOOK \
  ISPATIALGYM_LAZY_FRAMES ISPATIALGYM_MESH_CACHE ISPATIALGYM_RB_DUMP_WORLD ISPATIALGYM_RECORD_BEHAVIOR_PROPRIO ISPATIALGYM_SHARD_NO_DEPTH \
  ISPATIALGYM_SHARD_RGB_ENCODER ISPATIALGYM_LAB_CACHE ISPATIALGYM_BAND_TRUNK_CHECK
export NUMPY_MADVISE_HUGEPAGE=0
# owner 2026-10-11 11:46 (eval flows only; the code default stays 3 for the lab jobs): no cuRobo warm-up - instances and demo
# trajectories are identical with 0, 1 and 3 iterations (cuB), the warm-up cost 70-170 s per process; a fixed string hash seed,
# so LeRobot's task index order (lerobot dataset_writer: list(set(tasks))) is the same in every run
export ISPATIALGYM_CUROBO_WARMUP_ITERS=0 PYTHONHASHSEED=0
if [ -n "${SLURM_JOB_ID:-}" ]; then
  # HOME and the sampler caches per job: node-local /tmp with >= 30 GB free, else under $E on NFS
  if [ "$(df --output=avail -k /tmp 2>/dev/null | tail -1)" -gt 30000000 ] 2>/dev/null && mkdir -p /tmp/$USER/isge_$SLURM_JOB_ID 2>/dev/null; then
    JB=/tmp/$USER/isge_$SLURM_JOB_ID
  else
    JB=${ISGF_JB_NFS:-/vision/u/minyeong/projects/isg_home/trainfast/jobs}/$SLURM_JOB_ID   # shiyuc mode: under /vision/u/shiyuc/minyeong
  fi
  mkdir -p $JB/home
  export HOME=$JB/home XDG_CACHE_HOME=$JB/home/.cache TORCHINDUCTOR_CACHE_DIR=$JB/inductor TRITON_CACHE_DIR=$JB/triton HF_LEROBOT_HOME=$JB/lerobot_home
  export ISPATIALGYM_REACH_BANDS=$JB/reach_bands ISPATIALGYM_CACHE_DIR=$JB/isg_cache ISPATIALGYM_SAMPLING_CACHE=$JB/isg_cache/sampling \
    ISPATIALGYM_HELD_HOLD_CACHE=$JB/isg_cache/held_hold.json ISPATIALGYM_REACH_VOLUME=$JB/reach_volume
  mkdir -p $TORCHINDUCTOR_CACHE_DIR $TRITON_CACHE_DIR $ISPATIALGYM_REACH_BANDS $ISPATIALGYM_CACHE_DIR $ISPATIALGYM_REACH_VOLUME
  # copies: the bands shipped with the code and the robot's reach volume (a band or volume the sampler computes stays in the job)
  [ -n "$(ls -A $ISPATIALGYM_REACH_BANDS 2>/dev/null)" ] || cp --preserve=timestamps $R/runlogs/reach_bands_20260915/bands/* $ISPATIALGYM_REACH_BANDS/ 2>/dev/null
  # the 55-task jobs (ISGE_BAND_STORE=1, job_cand.sh; owner plan 2026-10-11 13:25 W6): also the band session's finished bands, read-only
  # (a copy in the job; the store is never written)
  if [ "${ISGE_BAND_STORE:-0}" = 1 ]; then
    cp --preserve=timestamps ${ISGF_LAB_BAND_STORE:-/vision/u/minyeong/projects/ispatialgym-lab-vec-eval-cache/reach_bands}/* $ISPATIALGYM_REACH_BANDS/ 2>/dev/null
    # and the bands the eval session computed itself from its own snapshots (owner 2026-10-11 W2 rule; touching contact bands, scaled targets)
    cp --preserve=timestamps ${ISGF_EVAL_BANDS:-$E/bands_eval}/*.json ${ISGF_EVAL_BANDS:-$E/bands_eval}/*.npz $ISPATIALGYM_REACH_BANDS/ 2>/dev/null
  fi
  [ -n "$(ls -A $ISPATIALGYM_REACH_VOLUME 2>/dev/null)" ] || cp --preserve=timestamps ${ISGF_REACH_VOLUME_SRC:-/vision/u/minyeong/projects/isg_home/.cache/ispatialgym-vecenv/reach_volume}/* $ISPATIALGYM_REACH_VOLUME/ 2>/dev/null
  NCPU=${SLURM_CPUS_PER_TASK:-8}
  export MKL_NUM_THREADS=$NCPU OPENBLAS_NUM_THREADS=$NCPU
fi
cd $R
